mapper.select:
SELECT o.id, o.prescription_id,  AS order_name, COALESCE(o.pharmacy_name_snapshot, ph.name) AS pharmacy_name, o.status, o.logistics_status,
       (SELECT t.node FROM drug_order_logistics_trace t WHERE t.drug_order_id=o.id ORDER BY t.occurred_at DESC, t.id DESC LIMIT 1) AS latest_logistics_node,
       o.amount_cent, o.expire_at, p.name AS patient_name
FROM drug_order o INNER JOIN patient p ON p.id=o.patient_id AND p.deleted_at IS NULL LEFT JOIN pharmacy ph ON ph.id=o.pharmacy_id
WHERE o.patient_id=#{patientId} AND o.deleted_at IS NULL
AND o.status=#{status}
AND o.logistics_status=#{logisticsStatus}
AND  ILIKE CONCAT('%', #{keyword}, '%')
ORDER BY o.created_at DESC, o.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM drug_order o WHERE o.patient_id=#{patientId} AND o.deleted_at IS NULL
AND o.status=#{status}
AND o.logistics_status=#{logisticsStatus}
AND  ILIKE CONCAT('%', #{keyword}, '%')

mapper.update:
UPDATE drug_order_medication_reminder_activation
SET status = 'ACTIVATED', activated_at = #{activatedAt}, updated_at = #{activatedAt}
WHERE drug_order_id = #{drugOrderId}
  AND status = 'PENDING_RECEIPT'
  AND deleted_at IS NULL

UPDATE drug_order
SET logistics_status = #{targetLogisticsStatus},
    shipped_at = CASE WHEN #{targetLogisticsStatus} = 'IN_TRANSIT' THEN #{now} ELSE shipped_at END,
    delivered_at = CASE WHEN #{targetLogisticsStatus} = 'TO_RECEIVE' THEN #{now} ELSE delivered_at END,
    updated_at = #{now}
WHERE id = #{drugOrderId}
  AND status = 'PAID'
  AND logistics_status = #{expectedLogisticsStatus}
  AND deleted_at IS NULL
